using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Windows.Forms;

namespace MP1SkinStudio
{
    public static partial class SelfTests
    {
        static SkinProject CollectionDemo(){var p=Demo();p.OpenPage("demo.collections.xml");return p;}
        static SkinControl CollectionControl(SkinProject p,string type){return p.Controls.First(c=>c.Get("type")==type);}
        static void RunCollectionTests(string root)
        {
            RunCollectionInteractionTests(root);
            Test("Project format 4 protects collection data while format 3 remains readable",()=>{
                var p=CollectionDemo();string path=Path.Combine(root,"collection-format.mp1skinproj");ProjectFile.Save(p,path);using(var zip=ZipFile.OpenRead(path))using(var reader=new StreamReader(zip.GetEntry("project.xml").Open()))Check(reader.ReadToEnd().Contains("version=\"4\""),"New project does not use format 4.");RewriteManifest(path,text=>{var doc=new System.Xml.XmlDocument();doc.LoadXml(text);doc.DocumentElement.SetAttribute("version","3");var node=doc.SelectSingleNode("/skinStudioProject/editorState/collection");node.ParentNode.RemoveChild(node);return doc.OuterXml;});Check(ProjectFile.Load(path).Editor.Collection.Mode=="auto","Format 3 is incompatible.");});
            Test("Facade navigation uses logical IDs and changes only the active source template",()=>{
                var p=CollectionDemo();string key=p.InsertControl("demo.collections.xml","button");var button=p.Controls.First(c=>c.Key==key);var facade=CollectionControl(p,"facadeview");p.ConnectNavigation(button,CollectionControl(p,"listcontrol"),"onright",false);Check(p.NavigationTarget(p.Controls.First(c=>c.Key==key),"onright").Get("type")=="facadeview","Target did not resolve to the facade.");p.Editor.Collection.Mode="filmstrip";p.ConnectNavigation(CollectionControl(p,"facadeview"),p.Controls.First(c=>c.Key==key),"onleft",false);Check(CollectionControl(p,"filmstrip").Get("onleft")==button.Get("id")&&CollectionControl(p,"listcontrol").Get("onleft")!=button.Get("id"),"Inactive template was edited.");});
            Test("Native Hidden and Collapsed visibility remains invisible under preview conditions",()=>{
                var p=CollectionDemo();var c=p.Controls.First(x=>x.Get("type")=="textbox");c.Properties["Visibility"]=new PropertyValue("Hidden","",true);Check(new PreviewState(p).Visible(c)==false,"Hidden became visible.");c.Properties["Visibility"]=new PropertyValue("Collapsed","",true);Check(new PreviewState(p).Visible(c)==false,"Collapsed became visible.");});
            Test("Facades display exactly one subview and preserve every XML control",()=>{
                var p=CollectionDemo();int count=p.Controls.Count;string xml=p.Controls[0].Source.Text;foreach(string mode in new[]{"list","smallicons","largeicons","filmstrip","coverflow"}){p.Editor.Collection.Mode=mode;var active=p.Controls.Where(c=>c.RuntimeParent!=null&&c.RuntimeParent.Get("type")=="facadeview"&&CollectionSettings.Active(p,c)).ToArray();Check(active.Length==1&&CollectionSettings.Kind(active[0],mode)==mode,"Multiple or incorrect views are active.");}Check(count==p.Controls.Count&&xml==p.Controls[0].Source.Text&&!p.Dirty,"View switching changes XML.");});
            Test("Collection property fields apply to concrete compatible subviews only",()=>{
                var p=CollectionDemo();var row=CollectionProperties.Find("textureHeight");var spacing=CollectionProperties.Find("spaceBetweenItems");Check(row.AppliesTo(CollectionControl(p,"listcontrol"))&&row.AppliesTo(CollectionControl(p,"filmstrip"))&&!row.AppliesTo(CollectionControl(p,"facadeview"))&&!row.AppliesTo(CollectionControl(p,"coverflow")),"Row fields apply to incompatible controls.");Check(spacing.AppliesTo(CollectionControl(p,"listcontrol"))&&!spacing.AppliesTo(CollectionControl(p,"thumbnailpanel")),"Spacing applies to the wrong view.");Check(CollectionProperties.Fields.Select(f=>f.Key).Distinct().Count()==CollectionProperties.Fields.Length&&CollectionProperties.Fields.All(f=>f.Label.Length>0),"Duplicate or unlabeled collection properties.");});
            Test("Collection property dimensions and spacing reject invalid numeric input",()=>{
                foreach(var field in CollectionProperties.Fields){field.Validate("12");foreach(string invalid in new[]{"-1","1.5","NaN","2147483648","#height",""})Reject(()=>field.Validate(invalid));if(field.Key=="spaceBetweenItems")field.Validate("0");else Reject(()=>field.Validate("0"));}});
            Test("Missing facade views fall back to an existing template",()=>{
                var p=CollectionDemo();p.Editor.Collection.Mode="playlist";Check(CollectionSettings.EffectiveMode(p)=="list","A missing template was invented.");});
            Test("Facade conditions and selected sample data follow preview state",()=>{
                var p=CollectionDemo();p.Editor.Collection.Mode="coverflow";p.Editor.Collection.Focus=2;var state=new PreviewState(p);state.UpdateCollectionValues();Check(state.Evaluate("facadeview.coverflow",new HashSet<string>())==true&&state.Evaluate("facadeview.list",new HashSet<string>())==false&&state.Values["#selecteditem"]==p.Editor.Collection.Items[2].Title&&state.Values["#itemcount"]=="6","Collection state is stale.");p.Editor.Preview.Values["#selecteditem"]="Custom value";state=new PreviewState(p);state.UpdateCollectionValues();Check(state.Values["#selecteditem"]=="Custom value","Custom sample value was overwritten.");});
            Test("Shared facade IDs form one logical identity while real collisions remain protected",()=>{
                var p=CollectionDemo();Check(p.LogicalControls().Count(c=>c.Get("id")=="50")==1&&new PreviewState(p).Evaluate("control.isvisible(50)",new HashSet<string>())==true,"Facade subviews create false ambiguity.");Check(!SkinAudit.Run(p).Issues.Any(i=>i.Code=="DUPLICATE_ID"),"Facade ID was reported as an error.");});
            Test("List geometry uses textureHeight and spaceBetweenItems",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");var tiles=CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection);Check(tiles.Length==6&&tiles[1].Bounds.Y-tiles[0].Bounds.Y==95&&tiles[0].Title.X==200&&tiles[0].Detail.X==920,"Incorrect row grid or text offsets.");});
            Test("List selection scrolls into view without changing XML positions",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");p.Editor.Collection.Focus=5;var r=LayoutTools.Bounds(c);r.Height=190;var tiles=CollectionGeometry.Tiles(c,r,p.Editor.Collection);Check(tiles.Length==2&&tiles[0].Index==4&&tiles[1].Index==5&&tiles[1].Selected&&c.Get("posY")=="250","Selection is outside visible rows.");});
            Test("Icon grids use large dimensions independently of small icons",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"thumbnailpanel");var small=CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection);p.Editor.Collection.Mode="largeicons";var big=CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection);Check(small[0].Bounds.Width==270&&big[0].Bounds.Width==350&&big[0].Image.Width==300,"Large icon dimensions were ignored.");});
            Test("Filmstrips and coverflow produce different static geometries",()=>{
                var p=CollectionDemo();var film=CollectionControl(p,"filmstrip");var flow=CollectionControl(p,"coverflow");p.Editor.Collection.Focus=1;var a=CollectionGeometry.Tiles(film,LayoutTools.Bounds(film),p.Editor.Collection);var b=CollectionGeometry.Tiles(flow,LayoutTools.Bounds(flow),p.Editor.Collection);Check(a.Length>1&&a[0].Bounds.Y==a[1].Bounds.Y&&b.Single(t=>t.Selected).Bounds.Width>b.First(t=>!t.Selected).Bounds.Width,"Collection views were treated as identical.");});
            Test("Filmstrip labels honor texture dimensions and negative text offsets independently of thumbnails",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"filmstrip");p.Edit(c,new Dictionary<string,string>{{"textureWidth","230"},{"textureHeight","327"},{"thumbHeight","300"},{"thumbPosY","5"},{"textXOff","17"},{"textYOff","-2000"}},"Filmstrip geometry fixture");c=CollectionControl(p,"filmstrip");string xml=c.Source.Text;var bounds=LayoutTools.Bounds(c);var tile=CollectionGeometry.Tiles(c,bounds,p.Editor.Collection).First();Check(tile.Title.X==bounds.X+17&&tile.Title.Y==bounds.Y+327-2000&&tile.Title.Width==230&&tile.Title.Height==327&&tile.Title.Bottom<bounds.Top,"Filmstrip label offsets or dimensions were ignored.");Check(tile.Image.Y==bounds.Y+5&&tile.Image.Height==300&&c.Source.Text==xml,"Thumbnail geometry or XML changed.");});
            Test("Empty collections and selections beyond the last item are bounded",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");p.Editor.Collection.Focus=49;Check(p.Editor.Collection.SelectedIndex==5,"Selection is not bounded.");p.Editor.Collection.Items.Clear();Check(p.Editor.Collection.SelectedIndex==-1&&CollectionGeometry.Tiles(c,LayoutTools.Bounds(c),p.Editor.Collection).Length==0,"Empty collection is invalid.");});
            Test("Collection data is deep-copied and unsafe image paths are rejected",()=>{
                var settings=new CollectionSettings();var copy=settings.Copy();copy.Items[0].Title="Neu";Check(settings.Items[0].Title!="Neu","Copy shares mutable items.");copy.Items[0].Image="../private.png";Reject(copy.Validate);copy.Items[0].Image="C:\\private.png";Reject(copy.Validate);});
            Test("Projects save collection views and data independently of skin ZIP exports",()=>{
                var p=CollectionDemo();p.Editor.Collection.Mode="filmstrip";p.Editor.Collection.Focus=3;p.Editor.Collection.Items[1].Title="Change & Test";string signature=ProjectFile.ContentSignature(p);string file=Path.Combine(root,"collection.mp1skinproj");ProjectFile.Save(p,file);var loaded=ProjectFile.Load(file);Check(ProjectFile.ContentSignature(loaded)==signature&&loaded.Editor.Collection.Items[1].Title=="Change & Test"&&!loaded.Dirty&&loaded.Undo.Count==0,"Collection snapshot is not lossless.");p.SetControlText(p.Controls.First(c=>c.Get("type")=="textbox"),"New text",false);file=Path.Combine(root,"collection-export.zip");p.Export(file);using(var zip=ZipFile.OpenRead(file)){Check(zip.Entries.Count==2&&zip.GetEntry("demo.collections.xml")!=null&&zip.GetEntry("_SkinStudio-Instructions.txt")!=null,"Sample data leaked into the skin ZIP.");}});
            Test("Font sizes include MP1 point conversion after 576-line scaling",()=>{
                var spec=new SkinFontSpec{Height=24};Check(spec.Pixels(1080)==60&&spec.Pixels(720)==40,"Incorrect point-to-pixel scaling.");spec.Height=12;Check(Math.Abs(spec.Pixels(1080)-22*96f/72f)<.001f,"Fractional point height was not truncated before conversion.");});
            Test("Font families, styles and aliases load from fonts.xml",()=>{
                string folder=Path.Combine(root,"font-spec");Directory.CreateDirectory(folder);Write(folder,"fonts.xml","<fonts><font><name>A</name><filename>Segoe UI</filename><height>24</height><bold>yes</bold><italic>yes</italic></font><alias><name>B</name><fontname>A</fontname></alias><alias><name>C</name><fontname>D</fontname></alias><alias><name>D</name><fontname>C</fontname></alias></fonts>");Write(folder,"main.xml",Xml("<label>Text</label>"));var p=new SkinProject(folder);p.OpenPage("main.xml");Check(p.FontSpecs["B"].Family=="Segoe UI"&&p.FontSpecs["B"].Style==(FontStyle.Bold|FontStyle.Italic)&&!p.FontSpecs.ContainsKey("C"),"Incorrect font style or alias cycle.");});
            Test("Text offsets and aspect ratios remain within control bounds",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"listcontrol");var own=SkinSource.FromText("<control><type>button</type><textXOff>20</textXOff><textYOff>8</textYOff></control>","button.xml");var button=new SkinControl{Node=own.Root};button.Properties["type"]=new PropertyValue("button","",true);button.Properties["textXOff"]=new PropertyValue("20","",true);button.Properties["textYOff"]=new PropertyValue("8","",true);Check(SurfaceGeometry.TextArea(button,new RectangleF(100,200,300,80))==new RectangleF(120,208,260,72),"Incorrect text offsets.");Check(SurfaceGeometry.Fit(new RectangleF(0,0,200,100),new Size(100,100),true)==new RectangleF(50,0,100,100),"Image proportions are distorted.");});
            Test("Image tinting applies RGB and alpha without changing original images",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"textbox");c.Properties["colordiffuse"]=new PropertyValue("80ff0000","",true);using(var canvas=new SkinCanvas{Project=p,State=new PreviewState(p)})using(var image=new Bitmap(8,8))using(var output=new Bitmap(32,32))using(var a=Graphics.FromImage(image))using(var b=Graphics.FromImage(output)){a.Clear(Color.White);canvas.SurfaceImageForTest(b,c,image,new RectangleF(4,4,24,24));var pixel=output.GetPixel(16,16);Check(pixel.R>240&&pixel.G<5&&pixel.B<5&&pixel.A>=125&&pixel.A<=130&&image.GetPixel(4,4).ToArgb()==Color.White.ToArgb(),"Incorrect image tint or alpha.");}});
            Test("Textbox wrapping draws additional lines within its bounds",()=>{
                var p=CollectionDemo();var c=CollectionControl(p,"textbox");using(var canvas=new SkinCanvas{Project=p,State=new PreviewState(p)})using(var output=new Bitmap(240,220))using(var g=Graphics.FromImage(output)){canvas.SurfaceTextForTest(g,c,"Long preview text with multiple words and multiple lines",new RectangleF(20,20,180,180));bool lower=false;for(int y=70;y<200;y++)for(int x=20;x<200;x++)if(output.GetPixel(x,y).A>0)lower=true;Check(lower&&output.GetPixel(2,2).A==0&&output.GetPixel(220,200).A==0,"No wrapping or text outside the field.");}});
        }
    }
    public sealed partial class SkinCanvas
    {
        internal void SurfaceImageForTest(Graphics g,SkinControl c,Bitmap image,RectangleF rect){SurfaceImage(g,c,image,rect);}
        internal void SurfaceTextForTest(Graphics g,SkinControl c,string text,RectangleF rect){SurfaceText(g,c,text,rect,false,"font","textcolor","align",true);}
    }
    public sealed partial class StudioForm
    {
        void RunCollectionUiSmoke(string directory,Action<bool,string> verify)
        {
            PrepareCollectionPreview("list");var facade=project.Controls.First(c=>c.Get("type")=="facadeview");SelectControl(facade);string xml=facade.Source.Text,signature=ProjectFile.XmlSignature(project);
            verify(canvas.ExerciseDrawn(project.Controls.First(c=>c.Get("type")=="listcontrol"))&&!canvas.ExerciseDrawn(project.Controls.First(c=>c.Get("type")=="filmstrip")),"Facades display only the active subview on the canvas");
            using(var dialog=new CollectionDialog(project.Editor.Collection)){dialog.Show(this);Application.DoEvents();dialog.ConfigureForTest("coverflow",2,"A movie | 2026 | Studio/Icon-Movie.png\r\nAnother movie | 2025 | Studio/Icon-Pictures.png");dialog.SubmitForTest();ApplyCollectionSettings(dialog.Result);}
            verify(CollectionSettings.EffectiveMode(project)=="coverflow"&&state.Values["#selecteditem"]=="Another movie"&&canvas.ExerciseDrawn(project.Controls.First(c=>c.Get("type")=="coverflow")),"Collection dialogs apply views, selection and custom data");
            verify(ProjectFile.XmlSignature(project)==signature&&project.Undo.Count==0&&!project.Dirty&&SessionNeedsSaving(),"Collection state is marked for saving independently of XML and undo");
            string file=Path.Combine(directory,"Collection.mp1skinproj");SaveSession(file);ResumeSession(file);verify(project.Editor.Collection.Mode=="coverflow"&&project.Editor.Collection.Focus==1&&project.Editor.Collection.Items.Count==2&&!SessionNeedsSaving(),"Opening projects restores collection state and saved-state status");
            using(var dialog=new CollectionDialog(project.Editor.Collection)){dialog.ConfigureForTest("list",1,"Test | Details | ../not-allowed.png");bool rejected=false;try{dialog.CollectForTest();}catch{rejected=true;}verify(rejected&&project.Editor.Collection.Mode=="coverflow","Collection dialogs reject invalid image paths before applying changes");}
            selected=project.Controls.First(c=>c.Get("type")=="facadeview");SelectControl(selected);bool seen=false;using(var timer=new Timer{Interval=30}){timer.Tick+=(s,e)=>{var dialog=Application.OpenForms.OfType<CollectionDialog>().FirstOrDefault();if(dialog==null)return;timer.Stop();seen=true;dialog.DialogResult=DialogResult.Cancel;dialog.Close();};var menu=(StudioMenu)ProtectionMenu();int index=menu.Items.Cast<ToolStripItem>().ToList().FindIndex(i=>i.Text.StartsWith("Collection Preview",StringComparison.Ordinal));timer.Start();menu.Show(tree,new Point(10,10));menu.ChooseForTest(index);timer.Stop();}verify(seen&&project.Editor.Collection.Mode=="coverflow"&&!SessionNeedsSaving(),"Element menus open collection dialogs and cancellation preserves data");
            PrepareCollectionPreview("largeicons");RenderTo(Path.Combine(directory,"Collection-Large-Icons.png"));Show();Application.DoEvents();verify(project.Controls[0].Source.Text==xml,"Rendered collections preserve original XML");
            LoadProject(DemoRoot(),"demo.xml");SelectControl(project.Controls.First(c=>c.Name=="Movies"));string original=selected.Source.Text;fields["textXOff"].Text="25";fields["textYOff"].Text="10";fields["textalign"].Text="right";fields["textvalign"].Text="middle";Apply();verify(selected.Get("textXOff")=="25"&&selected.Get("textalign")=="right"&&SurfaceGeometry.TextArea(selected,canvas.BoundsOf(selected)).X==canvas.BoundsOf(selected).X+25,"Text spacing and inner alignment can be edited atomically through properties");undo.PerformClick();verify(selected.Source.Text==original&&!project.Dirty,"Undoing text-rendering changes restores exact source text");
        }
    }
}
